	require 'conn.php';
	$sql = "DROP DATABASE IF EXISTS penjualan;
			CREATE DATABASE IF NOT EXISTS penjualan;
			USE penjualan;
			DROP TABLE IF EXISTS transaksi_detail;
			DROP TABLE IF EXISTS transaksi;
			DROP TABLE IF EXISTS barang;
			DROP TABLE IF EXISTS pelanggan;
			DROP TABLE IF EXISTS supplier;
			DROP TABLE IF EXISTS user;
			DROP TABLE IF EXISTS pembayaran;
			SET FOREIGN_KEY_CHECKS = 0;
			CREATE TABLE pelanggan (
		    id VARCHAR(20) PRIMARY KEY,
		    nama VARCHAR(100) NOT NULL,
		    jenis_kelamin ENUM('L','P') NOT NULL,
		    telp VARCHAR(12),
		    alamat TEXT
			) ENGINE=InnoDB;
			CREATE TABLE barang (
		    id INT AUTO_INCREMENT PRIMARY KEY,
		    kode_barang VARCHAR(10) NOT NULL,
		    nama_barang VARCHAR(100) NOT NULL,
		    harga INT NOT NULL,
		    stok INT NOT NULL,
		    supplier_id INT NOT NULL,
		    FOREIGN KEY (supplier_id) REFERENCES supplier(id)
			) ENGINE=InnoDB;
			CREATE TABLE supplier (
		    id INT AUTO_INCREMENT PRIMARY KEY,
		    nama VARCHAR(100) NOT NULL,
		    telp VARCHAR(12),
		    alamat TEXT
			) ENGINE=InnoDB;
			CREATE TABLE transaksi (
		    id INT AUTO_INCREMENT PRIMARY KEY,
		    tanggal DATE NOT NULL,
		    keterangan TEXT,
		    total INT NOT NULL DEFAULT 0,
			pelanggan VARCHAR(20) NOT NULL,
			FOREIGN KEY (pelanggan) REFERENCES pelanggan(id)
			) ENGINE=InnoDB;
			CREATE TABLE transaksi_detail (
		    transaksi_id INT NOT NULL,
		    barang_id INT NOT NULL,
		    harga INT NOT NULL,
		    qty INT NOT NULL,
		    PRIMARY KEY (transaksi_id, barang_id),
		    FOREIGN KEY (transaksi_id) REFERENCES transaksi(id) ON UPDATE CASCADE ON DELETE CASCADE,
		    FOREIGN KEY (barang_id) REFERENCES barang(id) ON UPDATE CASCADE ON DELETE RESTRICT
			) ENGINE=InnoDB;
			CREATE TABLE pembayaran (
		    id INT AUTO_INCREMENT PRIMARY KEY,
		    waktu_bayar DATETIME NOT NULL,
		    total INT NOT NULL,
		    metode ENUM('TUNAI','TRANSFER','EDC') NOT NULL,
		    transaksi_id INT NOT NULL,
		    FOREIGN KEY (transaksi_id) REFERENCES transaksi(id) ON UPDATE CASCADE ON DELETE CASCADE
			) ENGINE=InnoDB;
			CREATE TABLE user (
		    id_user INT AUTO_INCREMENT PRIMARY KEY,
		    username VARCHAR(30) NOT NULL UNIQUE,
		    password VARCHAR(35) NOT NULL,
		    nama VARCHAR(50) NOT NULL,
		    alamat VARCHAR(150),
		    hp VARCHAR(20),
		    level TINYINT(1) NOT NULL
			) ENGINE=InnoDB;

